sp_widget.client_script:
api.controller = function ($scope,$window,$timeout,spUtil) {

    var c = this;

    /*
     * Initial client values.
     */
    c.records =
        c.data.records || [];

    c.stageCounts =
        c.data.stageCounts || {
            manager: 0,
            pending_l2_approval: 0,
            pending_hr_review: 0
        };

    c.selectedStatus =
        c.data.selectedStatus ||
        "manager";

    c.filters =
        angular.copy(
            c.data.filters || {
                requestNumber: "",
                courseType: "",
                courseFormat: "",
                country: ""
            }
        );

    c.courseTypes =
        c.data.courseTypes || [];

    c.courseFormats =
        c.data.courseFormats || [];

    c.countries =
        c.data.countries || [];

    c.requestNumberSuggestions =
        c.data.requestNumberSuggestions || [];

    c.filteredRequestSuggestions =
        angular.copy(
            c.requestNumberSuggestions
        );

    c.selectedRecord = null;

    c.sortOrder =
        c.data.sortOrder ||
        "desc";

    c.isLoading = false;
    c.isDownloading = false;

    c.showRequestSuggestions = false;
    c.requestSuggestionLoading = false;
    c.activeSuggestionIndex = -1;

    c.successMessage =
        c.data.successMessage || "";

    c.errorMessage =
        c.data.errorMessage || "";

    /*
     * Change approval stage.
     */
    c.changeStage = function (
        stage
    ) {

        if (
            c.isLoading ||
            !stage ||
            c.selectedStatus === stage
        ) {
            return;
        }

        c.selectedStatus = stage;
        c.selectedRecord = null;

        c.filters.requestNumber = "";

        c.showRequestSuggestions = false;
        c.activeSuggestionIndex = -1;

        c.loadRecords(
            "change_stage"
        );
    };

    /*
     * Load approval records.
     */
    c.loadRecords = function (
        actionName
    ) {

        if (c.isLoading) {
            return;
        }

        c.isLoading = true;
        c.successMessage = "";
        c.errorMessage = "";

        c.server.get({
            action:
                actionName || "load",

            selectedStatus:
                c.selectedStatus,

            filters:
                angular.copy(
                    c.filters
                ),

            sortOrder:
                c.sortOrder

        }).then(
            function (
                response
            ) {

                applyServerResponse(
                    response
                );

            },
            function () {

                c.errorMessage =
                    "Unable to load approval records.";

                spUtil.addErrorMessage(
                    c.errorMessage
                );

            }
        ).finally(
            function () {

                c.isLoading = false;
            }
        );
    };

    /*
     * Search.
     */
    c.search = function () {

        c.selectedRecord = null;
        c.closeRequestSuggestions();

        c.loadRecords(
            "search"
        );
    };

    /*
     * Reset filters.
     */
    c.resetFilters = function () {

        c.filters = {
            requestNumber: "",
            courseType: "",
            courseFormat: "",
            country: ""
        };

        c.selectedRecord = null;
        c.closeRequestSuggestions();

        c.loadRecords(
            "refresh"
        );
    };

    /*
     * Refresh.
     */
    c.refresh = function () {

        c.selectedRecord = null;
        c.closeRequestSuggestions();

        c.loadRecords(
            "refresh"
        );
    };

    /*
     * Sort records.
     */
    c.toggleSort = function () {

        c.sortOrder =
            c.sortOrder === "asc"
                ? "desc"
                : "asc";

        c.loadRecords(
            "refresh"
        );
    };

    /*
     * Select approval card.
     */
    c.selectRecord = function (
        record
    ) {

        if (!record) {
            return;
        }

        c.selectedRecord =
            angular.copy(
                record
            );

        c.selectedRecord.actionComments = "";
        c.selectedRecord.commentValidationError =
            false;
        c.selectedRecord.processing =
            false;

        c.successMessage = "";
        c.errorMessage = "";
    };

    /*
     * Close selected record.
     */
    c.closeSelectedRecord = function () {

        c.selectedRecord = null;
        c.successMessage = "";
        c.errorMessage = "";
    };

    /*
     * Approval actions.
     */
    c.approveSelected = function () {

        processDecision(
            "approve"
        );
    };

    c.rejectSelected = function () {

        processDecision(
            "reject"
        );
    };

    c.sendBackSelected = function () {

        processDecision(
            "send_back"
        );
    };

    /*
     * Process approve, reject or send back.
     */
    function processDecision(
        actionName
    ) {

        if (
            !c.selectedRecord ||
            c.selectedRecord.processing
        ) {
            return;
        }

        var comments =
            String(
                c.selectedRecord
                    .actionComments || ""
            ).trim();

        if (!comments) {

            c.selectedRecord
                .commentValidationError = true;

            c.errorMessage =
                "Please enter the comments.";

            spUtil.addErrorMessage(
                c.errorMessage
            );

            focusCommentsField();

            return;
        }

        c.selectedRecord
            .commentValidationError = false;

        c.selectedRecord.processing = true;

        c.successMessage = "";
        c.errorMessage = "";

        c.server.get({
            action:
                actionName,

            approvalSysId:
                c.selectedRecord
                    .approval_sys_id,

            applicationSysId:
                c.selectedRecord
                    .application_sys_id,

            comments:
                comments,

            selectedStatus:
                c.selectedStatus,

            filters:
                angular.copy(
                    c.filters
                ),

            sortOrder:
                c.sortOrder

        }).then(
            function (
                response
            ) {

                applyServerResponse(
                    response
                );

                if (
                    !c.errorMessage
                ) {
                    c.selectedRecord =
                        null;
                }

            },
            function () {

                c.errorMessage =
                    "Unable to process the approval action.";

                spUtil.addErrorMessage(
                    c.errorMessage
                );

            }
        ).finally(
            function () {

                if (
                    c.selectedRecord
                ) {
                    c.selectedRecord
                        .processing = false;
                }
            }
        );
    }

    /*
     * Download approved records.
     *
     * This function name exactly matches the HTML:
     * c.downloadApprovedRecords()
     */
    c.downloadApprovedRecords =
        function () {

            if (
                c.isDownloading
            ) {
                return;
            }

            c.isDownloading = true;
            c.successMessage = "";
            c.errorMessage = "";

            c.server.get({
                action:
                    "download_report",

                selectedStatus:
                    c.selectedStatus,

                filters:
                    angular.copy(
                        c.filters
                    ),

                sortOrder:
                    c.sortOrder

            }).then(
                function (
                    response
                ) {

                    var responseData =
                        response &&
                        response.data
                            ? response.data
                            : {};

                    c.successMessage =
                        responseData
                            .successMessage || "";

                    c.errorMessage =
                        responseData
                            .errorMessage || "";

                    if (
                        c.errorMessage
                    ) {

                        spUtil.addErrorMessage(
                            c.errorMessage
                        );

                        return;
                    }

                    if (
                        !responseData
                            .downloadReady
                    ) {

                        c.errorMessage =
                            "The report was not generated.";

                        spUtil.addErrorMessage(
                            c.errorMessage
                        );

                        return;
                    }

                    if (
                        !responseData
                            .fileContent
                    ) {

                        c.errorMessage =
                            "No report content was returned.";

                        spUtil.addErrorMessage(
                            c.errorMessage
                        );

                        return;
                    }

                    downloadCsvFile(
                        responseData
                            .fileContent,

                        responseData
                            .fileName ||
                        "ASEAN_My_Approved_Learning_Requests.csv"
                    );

                    if (
                        c.successMessage
                    ) {
                        spUtil.addInfoMessage(
                            c.successMessage
                        );
                    }

                },
                function (
                    error
                ) {

                    c.errorMessage =
                        "Unable to generate the report.";

                    spUtil.addErrorMessage(
                        c.errorMessage
                    );

                    console.error(
                        "Approval report server error:",
                        error
                    );

                }
            ).finally(
                function () {

                    c.isDownloading = false;
                }
            );
        };

    /*
     * Download CSV in browser.
     */
    function downloadCsvFile(
        fileContent,
        fileName
    ) {

        try {

            var csvText =
                "\uFEFF" +
                String(
                    fileContent || ""
                );

            var blob =
                new Blob(
                    [csvText],
                    {
                        type:
                            "text/csv;charset=utf-8;"
                    }
                );

            var urlCreator =
                $window.URL ||
                $window.webkitURL;

            if (
                !urlCreator ||
                !urlCreator.createObjectURL
            ) {
                throw new Error(
                    "Browser URL API is unavailable."
                );
            }

            var downloadUrl =
                urlCreator.createObjectURL(
                    blob
                );

            var downloadLink =
                document.createElement(
                    "a"
                );

            downloadLink.href =
                downloadUrl;

            downloadLink.download =
                fileName ||
                "ASEAN_My_Approved_Learning_Requests.csv";

            downloadLink.style.display =
                "none";

            /*
             * Required for some browser versions.
             */
            document.body.appendChild(
                downloadLink
            );

            /*
             * Native browser click.
             */
            if (
                typeof downloadLink.click ===
                "function"
            ) {
                downloadLink.click();
            } else {

                var clickEvent =
                    document.createEvent(
                        "MouseEvents"
                    );

                clickEvent.initMouseEvent(
                    "click",
                    true,
                    true,
                    $window,
                    0,
                    0,
                    0,
                    0,
                    0,
                    false,
                    false,
                    false,
                    false,
                    0,
                    null
                );

                downloadLink.dispatchEvent(
                    clickEvent
                );
            }

            /*
             * Clean up after click.
             */
            $timeout(
                function () {

                    if (
                        downloadLink.parentNode
                    ) {
                        downloadLink.parentNode
                            .removeChild(
                                downloadLink
                            );
                    }

                    urlCreator.revokeObjectURL(
                        downloadUrl
                    );

                },
                1000
            );

        } catch (
            downloadError
        ) {

            c.errorMessage =
                "The report was generated, but the browser could not download it.";

            spUtil.addErrorMessage(
                c.errorMessage
            );

            console.error(
                "ASEAN CSV download error:",
                downloadError
            );
        }
    }

    /*
     * Request-number typeahead.
     */
    c.onRequestNumberChange =
        function () {

            var searchText =
                String(
                    c.filters
                        .requestNumber || ""
                )
                    .toLowerCase()
                    .trim();

            c.activeSuggestionIndex =
                -1;

            if (!searchText) {

                c.filteredRequestSuggestions =
                    angular.copy(
                        c.requestNumberSuggestions
                    );

                c.showRequestSuggestions =
                    c.filteredRequestSuggestions
                        .length > 0;

                return;
            }

            c.filteredRequestSuggestions =
                c.requestNumberSuggestions
                    .filter(
                        function (
                            suggestion
                        ) {

                            var combinedText =
                                [
                                    suggestion
                                        .label || "",
                                    suggestion
                                        .courseTitle || "",
                                    suggestion
                                        .employeeName || ""
                                ]
                                    .join(" ")
                                    .toLowerCase();

                            return (
                                combinedText
                                    .indexOf(
                                        searchText
                                    ) !== -1
                            );
                        }
                    );

            c.showRequestSuggestions =
                true;
        };

    /*
     * Request number focus.
     */
    c.onRequestNumberFocus =
        function () {

            if (
                c.requestNumberSuggestions &&
                c.requestNumberSuggestions
                    .length > 0
            ) {
                c.onRequestNumberChange();
            }
        };

    /*
     * Delayed blur.
     */
    c.onRequestNumberBlur =
        function () {

            $timeout(
                function () {

                    c.closeRequestSuggestions();

                },
                200
            );
        };

    /*
     * Toggle request-number dropdown.
     */
    c.toggleRequestSuggestions =
        function (
            event
        ) {

            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            if (
                c.requestSuggestionLoading
            ) {
                return;
            }

            if (
                c.showRequestSuggestions
            ) {
                c.closeRequestSuggestions();
                return;
            }

            if (
                !c.requestNumberSuggestions ||
                c.requestNumberSuggestions
                    .length === 0
            ) {
                loadRequestSuggestions();
                return;
            }

            c.filteredRequestSuggestions =
                angular.copy(
                    c.requestNumberSuggestions
                );

            c.showRequestSuggestions =
                true;

            c.activeSuggestionIndex =
                -1;
        };

    /*
     * Select request suggestion.
     */
    c.selectRequestSuggestion =
        function (
            suggestion,
            event
        ) {

            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            if (!suggestion) {
                return;
            }

            c.filters.requestNumber =
                suggestion.value ||
                suggestion.label ||
                "";

            c.closeRequestSuggestions();

            c.search();
        };

    /*
     * Clear request number.
     */
    c.clearRequestNumber =
        function (
            event
        ) {

            if (event) {
                event.preventDefault();
                event.stopPropagation();
            }

            c.filters.requestNumber = "";

            c.filteredRequestSuggestions =
                angular.copy(
                    c.requestNumberSuggestions
                );

            c.closeRequestSuggestions();
        };

    /*
     * Keyboard typeahead handling.
     */
    c.handleRequestKeydown =
        function (
            event
        ) {

            if (!event) {
                return;
            }

            var suggestions =
                c.filteredRequestSuggestions ||
                [];

            var suggestionCount =
                suggestions.length;

            /*
             * Down arrow.
             */
            if (
                event.keyCode === 40
            ) {

                event.preventDefault();

                if (
                    !c.showRequestSuggestions
                ) {
                    c.onRequestNumberChange();
                }

                if (
                    suggestionCount > 0
                ) {
                    c.activeSuggestionIndex =
                        (
                            c.activeSuggestionIndex +
                            1
                        ) %
                        suggestionCount;
                }

                return;
            }

            /*
             * Up arrow.
             */
            if (
                event.keyCode === 38
            ) {

                event.preventDefault();

                if (
                    suggestionCount > 0
                ) {
                    c.activeSuggestionIndex =
                        c.activeSuggestionIndex <= 0
                            ? suggestionCount - 1
                            : c.activeSuggestionIndex - 1;
                }

                return;
            }

            /*
             * Enter.
             */
            if (
                event.keyCode === 13
            ) {

                event.preventDefault();

                if (
                    c.showRequestSuggestions &&
                    c.activeSuggestionIndex >= 0 &&
                    suggestions[
                        c.activeSuggestionIndex
                    ]
                ) {

                    c.selectRequestSuggestion(
                        suggestions[
                            c.activeSuggestionIndex
                        ],
                        event
                    );

                } else {

                    c.search();
                }

                return;
            }

            /*
             * Escape.
             */
            if (
                event.keyCode === 27
            ) {
                c.closeRequestSuggestions();
            }
        };

    /*
     * Close typeahead.
     */
    c.closeRequestSuggestions =
        function () {

            c.showRequestSuggestions =
                false;

            c.activeSuggestionIndex =
                -1;
        };

    /*
     * Load suggestions from server.
     */
    function loadRequestSuggestions() {

        c.requestSuggestionLoading =
            true;

        c.showRequestSuggestions =
            true;

        c.server.get({
            action:
                "get_request_suggestions",

            selectedStatus:
                c.selectedStatus,

            filters:
                angular.copy(
                    c.filters
                ),

            sortOrder:
                c.sortOrder

        }).then(
            function (
                response
            ) {

                var responseData =
                    response &&
                    response.data
                        ? response.data
                        : {};

                c.requestNumberSuggestions =
                    responseData
                        .requestNumberSuggestions ||
                    [];

                c.filteredRequestSuggestions =
                    angular.copy(
                        c.requestNumberSuggestions
                    );

                c.showRequestSuggestions =
                    true;

            },
            function () {

                c.errorMessage =
                    "Unable to load request-number suggestions.";

                spUtil.addErrorMessage(
                    c.errorMessage
                );

                c.closeRequestSuggestions();

            }
        ).finally(
            function () {

                c.requestSuggestionLoading =
                    false;
            }
        );
    }

    /*
     * Show send-back button for supported stages.
     */
    c.canSendBack =
        function () {

            return (
                c.selectedStatus ===
                    "manager" ||
                c.selectedStatus ===
                    "pending_l2_approval" ||
                c.selectedStatus ===
                    "pending_hr_review"
            );
        };

    /*
     * Stage label.
     */
    c.getSelectedStageLabel =
        function () {

            if (
                c.selectedStatus ===
                "manager"
            ) {
                return "In-Company Manager";
            }

            if (
                c.selectedStatus ===
                "pending_l2_approval"
            ) {
                return "Management L2";
            }

            if (
                c.selectedStatus ===
                "pending_hr_review"
            ) {
                return "HR Learning";
            }

            return "Approval";
        };

    /*
     * Back button.
     */
    c.goBack = function () {

        $window.location.href =
            "?id=manager_role_asean";
    };

    /*
     * Apply server response.
     */
    function applyServerResponse(
        response
    ) {

        var responseData =
            response &&
            response.data
                ? response.data
                : {};

        c.records =
            responseData.records || [];

        c.stageCounts =
            responseData.stageCounts || {
                manager: 0,
                pending_l2_approval: 0,
                pending_hr_review: 0
            };

        c.courseTypes =
            responseData.courseTypes ||
            c.courseTypes ||
            [];

        c.courseFormats =
            responseData.courseFormats ||
            c.courseFormats ||
            [];

        c.countries =
            responseData.countries ||
            c.countries ||
            [];

        c.requestNumberSuggestions =
            responseData
                .requestNumberSuggestions ||
            [];

        c.filteredRequestSuggestions =
            angular.copy(
                c.requestNumberSuggestions
            );

        c.successMessage =
            responseData.successMessage ||
            "";

        c.errorMessage =
            responseData.errorMessage ||
            "";

        if (
            c.successMessage
        ) {
            spUtil.addInfoMessage(
                c.successMessage
            );
        }

        if (
            c.errorMessage
        ) {
            spUtil.addErrorMessage(
                c.errorMessage
            );
        }
    }

    /*
     * Focus comment field.
     */
    function focusCommentsField() {

        $timeout(
            function () {

                var commentsField =
                    document.getElementById(
                        "approvalActionComments"
                    );

                if (
                    commentsField
                ) {
                    commentsField.focus();
                }

            },
            50
        );
    }

};

sp_widget.css:
.learning-widget {
    position: relative;
    min-height: 650px;
    overflow: visible;
    color: #222;
    background: #fff;
    border: 1px solid #333;
    font-family: Arial, Helvetica, sans-serif;
}

.widget-header {
    min-height: 65px;
    padding: 12px 15px 8px;
    background: #fff;
}

.widget-header h2 {
    display: inline-block;
    margin: 0;
    padding: 0 5px 8px;
    color: #ec6608;
    border-bottom: 3px solid #ec6608;
    font-size: 26px;
    font-weight: 600;
}

.stage-selection {
    display: flex;
    align-items: center;
    min-height: 52px;
    padding: 8px 15px;
    background: #fff;
    border-top: 4px solid #111;
    border-bottom: 1px solid #bdbdbd;
}

.stage-label {
    flex: 0 0 125px;
    font-size: 14px;
    text-decoration: underline;
}

.stage-tabs {
    display: flex;
    flex: 1;
    gap: 28px;
}

.stage-tab {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    flex: 1;
    max-width: 245px;
    min-height: 36px;
    padding: 5px 15px;
    color: #16415c;
    background: #eee;
    border: 0;
    border-radius: 7px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
}

.stage-tab:hover:not([disabled]) {
    background: #d9d9d9;
}

.stage-tab.active-stage {
    color: #fff;
    background: #f36f21;
}

.stage-tab[disabled] {
    cursor: not-allowed;
    opacity: 0.65;
}

.approval-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 23px;
    height: 23px;
    padding: 0 6px;
    color: #fff;
    background: #68737d;
    border-radius: 12px;
    font-size: 11px;
    font-weight: bold;
}

.active-stage .approval-count {
    color: #f36f21;
    background: #fff;
}

/* ============================================================
   FILTER TOOLBAR
   ============================================================ */

.toolbar {
    display: flex;
    align-items: stretch;
    min-height: 155px;
    overflow: visible;
    background: #e5e5e5;
    border-bottom: 1px solid #bdbdbd;
}

.download-section {
    flex: 0 0 145px;
    padding: 12px 10px;
}

.download-btn {
    width: 120px;
    min-height: 34px;
    padding: 6px 10px;
    color: #fff;
    background: #2ea94f;
    border: 0;
    font-size: 12px;
    font-weight: bold;
}

.download-btn:hover {
    background: #258d41;
}

.download-btn[disabled] {
    cursor: not-allowed;
    opacity: 0.65;
}

.download-btn i {
    margin-right: 6px;
}

.download-help {
    width: 120px;
    margin-top: 6px;
    color: #666;
    font-size: 10px;
    text-align: center;
}

.filters-container {
    flex: 1;
    padding: 10px 5px;
    overflow: visible;
}

.filter-row {
    display: flex;
    gap: 25px;
    margin-bottom: 8px;
    overflow: visible;
}

.filter-group {
    display: flex;
    align-items: center;
    flex: 1;
    min-width: 250px;
}

.filter-group label {
    flex: 0 0 115px;
    margin: 0;
    padding-right: 8px;
    font-size: 13px;
    font-weight: normal;
    text-align: right;
    text-decoration: underline;
}

.filter-group .form-control {
    flex: 1;
    height: 31px;
    padding: 4px 8px;
    color: #333;
    background: #fff;
    border: 1px solid #c4c4c4;
    border-radius: 0;
    font-size: 12px;
}

.ticket-status-field {
    color: #555 !important;
    background: #f5f5f5 !important;
}

.empty-filter {
    visibility: hidden;
}

/* ============================================================
   REQUEST NUMBER TYPEAHEAD
   ============================================================ */

.request-number-filter {
    overflow: visible;
}

.request-typeahead {
    position: relative;
    flex: 1;
    min-width: 0;
    overflow: visible;
    z-index: 1000;
}

.request-input-wrapper {
    position: relative;
    display: flex;
    width: 100%;
}

.request-number-input {
    width: 100%;
    padding-right: 58px !important;
}

.request-dropdown-button,
.request-clear-button {
    position: absolute;
    top: 1px;
    width: 27px;
    height: 29px;
    padding: 0;
    color: #666;
    background: transparent;
    border: 0;
    z-index: 2;
}

.request-dropdown-button {
    right: 1px;
}

.request-clear-button {
    right: 28px;
}

.request-dropdown-button:hover,
.request-clear-button:hover {
    color: #f36f21;
    background: #f2f2f2;
}

.request-dropdown-button[disabled] {
    cursor: not-allowed;
    opacity: 0.5;
}

.request-suggestion-dropdown {
    position: absolute;
    top: 33px;
    left: 0;
    right: 0;
    z-index: 9999;
    max-height: 260px;
    overflow-y: auto;
    background: #fff;
    border: 1px solid #aaa;
    box-shadow: 0 5px 12px rgba(0, 0, 0, 0.22);
}

.request-suggestion-item {
    display: block;
    width: 100%;
    padding: 8px 10px;
    color: #333;
    background: #fff;
    border: 0;
    border-bottom: 1px solid #eee;
    text-align: left;
    cursor: pointer;
}

.request-suggestion-item:last-child {
    border-bottom: 0;
}

.request-suggestion-item:hover,
.request-suggestion-item.active-suggestion {
    background: #fff1e8;
}

.suggestion-number {
    display: block;
    color: #0077b5;
    font-size: 13px;
    font-weight: bold;
}

.suggestion-course {
    display: block;
    margin-top: 2px;
    color: #333;
    font-size: 11px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.suggestion-employee {
    display: block;
    margin-top: 2px;
    color: #777;
    font-size: 10px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.request-suggestion-loading,
.request-no-suggestions {
    padding: 12px 10px;
    color: #666;
    font-size: 11px;
    text-align: center;
}

.request-suggestion-loading i {
    margin-right: 5px;
}

/* ============================================================
   FILTER BUTTONS
   ============================================================ */

.filter-button-row {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
}

.filter-btn {
    min-width: 90px;
    height: 31px;
    color: #fff;
    border: 0;
    font-size: 12px;
    font-weight: bold;
}

.search-btn {
    background: #008fd3;
}

.search-btn:hover {
    background: #007cb8;
}

.reset-btn {
    background: #777;
}

.reset-btn:hover {
    background: #5f5f5f;
}

.toolbar-actions {
    display: flex;
    flex: 0 0 46px;
    flex-direction: column;
    gap: 5px;
    padding: 10px 5px 8px 0;
}

.icon-btn {
    width: 36px;
    height: 32px;
    padding: 0;
    color: #fff;
    background: #2ea94f;
    border: 0;
    font-size: 17px;
}

.icon-btn:hover {
    background: #258d41;
}

.icon-btn[disabled],
.filter-btn[disabled] {
    cursor: not-allowed;
    opacity: 0.65;
}

.widget-message {
    margin: 10px 13px;
    padding: 9px 12px;
}

.loading-message {
    padding: 50px 20px;
    text-align: center;
}

/* ============================================================
   APPROVAL WORKSPACE
   ============================================================ */

.approval-workspace {
    display: flex;
    min-height: 470px;
    padding: 12px 13px 75px;
}

.approval-list-panel {
    flex: 0 0 35%;
    min-width: 290px;
    max-width: 410px;
    background: #f5f5f5;
    border: 1px solid #d5d5d5;
}

.list-panel-header {
    display: flex;
    justify-content: space-between;
    padding: 10px 14px;
    background: #eee;
    font-weight: bold;
}

.list-record-count {
    min-width: 25px;
    padding: 4px 7px;
    color: #fff;
    background: #68737d;
    border-radius: 13px;
    text-align: center;
}

.approval-cards {
    max-height: 620px;
    padding: 10px;
    overflow-y: auto;
}

.approval-card {
    display: block;
    width: 100%;
    margin-bottom: 10px;
    padding: 12px;
    background: #fff;
    border: 1px solid #d7d7d7;
    border-left: 4px solid transparent;
    text-align: left;
    cursor: pointer;
}

.approval-card:hover,
.approval-card.selected-card {
    border-left-color: #f36f21;
    background: #fffaf6;
}

.card-top-row,
.card-status-row {
    display: flex;
    justify-content: space-between;
}

.card-request-number {
    color: #0077b5;
    font-weight: bold;
}

.card-course-title {
    margin: 8px 0;
    font-weight: bold;
}

.card-detail-row {
    display: grid;
    grid-template-columns: 95px 1fr;
    min-height: 22px;
    font-size: 11px;
}

.card-label {
    font-weight: bold;
}

.card-status {
    padding: 3px 8px;
    color: #fff;
    background: #f36f21;
    border-radius: 10px;
    font-size: 10px;
}

.card-view-text {
    color: #0077b5;
    font-size: 11px;
    font-weight: bold;
}

.no-records-card {
    padding: 40px 20px;
    color: #666;
    text-align: center;
}

.no-records-card i {
    margin-bottom: 10px;
    color: #f36f21;
    font-size: 30px;
}

/* ============================================================
   DETAIL PANEL
   ============================================================ */

.approval-detail-panel {
    flex: 1;
    border: 1px solid #d5d5d5;
    border-left: 0;
}

.detail-empty-state {
    min-height: 470px;
    padding: 120px 35px;
    text-align: center;
}

.empty-state-icon {
    color: #f36f21;
    font-size: 42px;
}

.empty-state-title {
    margin-top: 12px;
    font-size: 18px;
    font-weight: bold;
}

.empty-state-text {
    margin-top: 8px;
    color: #666;
}

.selected-record-header {
    display: flex;
    justify-content: space-between;
    padding: 10px 16px;
    background: #f4f4f4;
}

.selected-record-caption {
    color: #666;
    font-size: 11px;
}

.selected-record-number {
    color: #0077b5;
    font-weight: bold;
}

.close-selected-btn {
    width: 31px;
    height: 31px;
    color: #fff;
    background: #777;
    border: 0;
    border-radius: 50%;
}

.close-selected-btn:hover {
    background: #555;
}

.selected-record-body {
    max-height: 620px;
    padding: 16px;
    overflow-y: auto;
}

.detail-section {
    margin-bottom: 20px;
}

.detail-section-title {
    display: inline-block;
    margin-bottom: 12px;
    border-bottom: 2px solid #222;
    font-weight: bold;
}

.summary-detail-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(190px, 1fr));
    gap: 12px 24px;
}

.summary-detail-item {
    display: grid;
    grid-template-columns: 145px 1fr;
    word-break: break-word;
}

.summary-detail-label {
    font-weight: bold;
}

.selected-status-badge {
    display: inline-block;
    padding: 4px 10px;
    color: #fff;
    background: #f36f21;
    border-radius: 11px;
}

/* ============================================================
   APPROVAL COMMENTS
   ============================================================ */

.previous-comments-section {
    margin-bottom: 20px;
    padding: 14px 16px;
    background: #f7f7f7;
    border: 1px solid #d5d5d5;
}

.previous-comment-card {
    margin-top: 12px;
    overflow: hidden;
    background: #fff;
    border: 1px solid #d7d7d7;
}

.previous-comment-heading {
    padding: 9px 12px;
    color: #333;
    background: #eee;
    border-bottom: 1px solid #d7d7d7;
    font-size: 13px;
    font-weight: bold;
}

.previous-comment-heading i {
    margin-right: 6px;
    color: #f36f21;
}

.previous-comment-text {
    min-height: 45px;
    padding: 12px;
    color: #444;
    font-size: 13px;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ============================================================
   COMMENT ENTRY AND ACTIONS
   ============================================================ */

.selected-comments-panel {
    padding: 15px 17px;
    background: #e9e9e9;
}

.comments-title {
    margin-bottom: 10px;
    color: #ec6608;
    font-weight: bold;
}

.mandatory-symbol {
    color: #c9302c;
}

.selected-comments-textarea {
    width: 100%;
    min-height: 105px;
    resize: vertical;
}

.comments-help {
    margin-top: 5px;
    color: #666;
    font-size: 11px;
}

.field-error {
    margin-top: 5px;
    color: #c9302c;
    font-weight: bold;
}

.selected-record-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 12px;
}

.decision-btn {
    min-width: 105px;
    min-height: 33px;
    padding: 7px 13px;
    color: #fff;
    border: 0;
    font-weight: bold;
}

.decision-btn[disabled] {
    cursor: not-allowed;
    opacity: 0.65;
}

.decision-btn i {
    margin-right: 5px;
}

.approve-btn {
    background: #2ea94f;
}

.approve-btn:hover:not([disabled]) {
    background: #258d41;
}

.send-back-btn {
    background: #f0ad4e;
}

.send-back-btn:hover:not([disabled]) {
    background: #dc982c;
}

.reject-btn {
    background: #d9534f;
}

.reject-btn:hover:not([disabled]) {
    background: #c9302c;
}

/* ============================================================
   BACK BUTTON
   ============================================================ */

.back-section {
    position: absolute;
    bottom: 10px;
    left: 10px;
}

.back-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    color: #ec6608;
    border: 2px solid #ec6608;
    border-radius: 50%;
    text-decoration: none;
}

.back-btn:hover,
.back-btn:focus {
    color: #fff;
    background: #ec6608;
    text-decoration: none;
}

/* ============================================================
   RESPONSIVE DESIGN
   ============================================================ */

@media screen and (max-width: 950px) {
    .approval-workspace {
        flex-direction: column;
    }

    .approval-list-panel,
    .approval-detail-panel {
        width: 100%;
        max-width: none;
    }

    .approval-detail-panel {
        border-left: 1px solid #d5d5d5;
    }
}

@media screen and (max-width: 800px) {
    .stage-selection,
    .toolbar,
    .filter-row {
        flex-direction: column;
    }

    .stage-selection {
        align-items: stretch;
    }

    .stage-label {
        flex: none;
        margin-bottom: 8px;
    }

    .stage-tabs {
        width: 100%;
        flex-direction: column;
        gap: 8px;
    }

    .stage-tab {
        max-width: none;
    }

    .download-section {
        flex: none;
    }

    .request-typeahead {
        width: 100%;
    }

    .filter-group {
        width: 100%;
        min-width: 0;
    }

    .filter-group label {
        flex: 0 0 120px;
    }

    .toolbar-actions {
        flex-direction: row;
        padding: 10px;
    }
}

@media screen and (max-width: 650px) {
    .summary-detail-grid {
        grid-template-columns: 1fr;
    }

    .summary-detail-item {
        grid-template-columns: 130px 1fr;
    }

    .selected-record-actions {
        flex-direction: column;
    }

    .decision-btn {
        width: 100%;
    }

    .filter-group {
        align-items: stretch;
        flex-direction: column;
    }

    .filter-group label {
        flex: none;
        margin-bottom: 4px;
        text-align: left;
    }
}

sp_widget.script:
(function () {

    var APPLICATION_TABLE =
        "x_1549902_asean_0_learning_application";

    var APPROVAL_TABLE =
        "sysapproval_approver";

    var STATUS_FIELD =
        "u_status";

    var MANAGER_COMMENTS_FIELD =
        "u_direct_manager_comments";

    var L2_COMMENTS_FIELD =
        "u_l2_manager_comments";

    var HR_COMMENTS_FIELD =
        "u_hr_comments";

    var currentUserId =
        gs.getUserID();

    data.records = [];
    data.stageCounts = {
        manager: 0,
        pending_l2_approval: 0,
        pending_hr_review: 0
    };

    data.courseTypes = [];
    data.courseFormats = [];
    data.countries = [];
    data.requestNumberSuggestions = [];

    data.loading = false;
    data.downloading = false;
    data.downloadReady = false;

    data.successMessage = "";
    data.errorMessage = "";
    data.fileContent = "";
    data.fileName = "";

    data.selectedStatus =
        input && input.selectedStatus
            ? String(input.selectedStatus)
            : "manager";

    data.filters = {
        requestNumber:
            input &&
            input.filters &&
            input.filters.requestNumber
                ? String(input.filters.requestNumber)
                : "",

        courseType:
            input &&
            input.filters &&
            input.filters.courseType
                ? String(input.filters.courseType)
                : "",

        courseFormat:
            input &&
            input.filters &&
            input.filters.courseFormat
                ? String(input.filters.courseFormat)
                : "",

        country:
            input &&
            input.filters &&
            input.filters.country
                ? String(input.filters.country)
                : ""
    };

    data.sortOrder =
        input && input.sortOrder
            ? String(input.sortOrder)
            : "desc";

    /*
     * Load filter choices for every request.
     */
    loadChoiceData();

    /*
     * Handle server actions.
     */
    if (input && input.action) {

        switch (String(input.action)) {

            case "load":
            case "search":
            case "refresh":
            case "change_stage":

                loadApprovalData();
                break;

            case "get_request_suggestions":

                loadRequestNumberSuggestions();
                break;

            case "approve":

                processApprovalAction(
                    "approved"
                );
                break;

            case "reject":

                processApprovalAction(
                    "rejected"
                );
                break;

            case "send_back":

                sendBackForReview();
                break;

            case "download_report":

                generateApprovalReport();
                break;

            default:

                loadApprovalData();
                break;
        }

    } else {

        loadApprovalData();
    }

    /*
     * Loads pending approval records for the selected stage.
     */
    function loadApprovalData() {

        data.records = [];
        data.successMessage = "";
        data.errorMessage = "";

        calculateStageCounts();

        var approvalGR =
            new GlideRecord(APPROVAL_TABLE);

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.addQuery(
            "approver",
            currentUserId
        );

        approvalGR.orderByDesc(
            "sys_created_on"
        );

        approvalGR.query();

        while (approvalGR.next()) {

            var learningGR =
                getLearningRecord(approvalGR);

            if (!learningGR) {
                continue;
            }

            if (
                !matchesSelectedStage(
                    learningGR,
                    approvalGR
                )
            ) {
                continue;
            }

            if (
                !matchesFilters(
                    learningGR
                )
            ) {
                continue;
            }

            data.records.push(
                buildApprovalRecord(
                    approvalGR,
                    learningGR
                )
            );
        }

        sortRecords();
        loadRequestNumberSuggestions();
    }

    /*
     * Calculates counts for all three approval tabs.
     */
    function calculateStageCounts() {

        data.stageCounts = {
            manager: 0,
            pending_l2_approval: 0,
            pending_hr_review: 0
        };

        var approvalGR =
            new GlideRecord(APPROVAL_TABLE);

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.addQuery(
            "approver",
            currentUserId
        );

        approvalGR.query();

        while (approvalGR.next()) {

            var learningGR =
                getLearningRecord(approvalGR);

            if (!learningGR) {
                continue;
            }

            var applicationStatus =
                String(
                    learningGR.getValue(
                        STATUS_FIELD
                    ) || ""
                );

            if (
                applicationStatus ===
                    "submitted" ||
                applicationStatus ===
                    "pending_manager_approval"
            ) {
                data.stageCounts.manager++;
            }

            if (
                applicationStatus ===
                "pending_l2_approval"
            ) {
                data.stageCounts
                    .pending_l2_approval++;
            }

            if (
                applicationStatus ===
                "pending_hr_review"
            ) {
                data.stageCounts
                    .pending_hr_review++;
            }
        }
    }

    /*
     * Determines whether a record belongs to the selected tab.
     */
    function matchesSelectedStage(
        learningGR,
        approvalGR
    ) {

        var applicationStatus =
            String(
                learningGR.getValue(
                    STATUS_FIELD
                ) || ""
            );

        if (
            data.selectedStatus ===
            "manager"
        ) {
            return (
                applicationStatus ===
                    "submitted" ||
                applicationStatus ===
                    "pending_manager_approval"
            );
        }

        if (
            data.selectedStatus ===
            "pending_l2_approval"
        ) {
            return (
                applicationStatus ===
                "pending_l2_approval"
            );
        }

        if (
            data.selectedStatus ===
            "pending_hr_review"
        ) {
            return (
                applicationStatus ===
                "pending_hr_review"
            );
        }

        return false;
    }

    /*
     * Applies request number, course type,
     * course format and country filters.
     */
    function matchesFilters(
        learningGR
    ) {

        var requestNumberFilter =
            normalize(
                data.filters.requestNumber
            );

        var courseTypeFilter =
            String(
                data.filters.courseType || ""
            );

        var courseFormatFilter =
            String(
                data.filters.courseFormat || ""
            );

        var countryFilter =
            String(
                data.filters.country || ""
            );

        if (requestNumberFilter) {

            var requestNumber =
                normalize(
                    learningGR.getDisplayValue(
                        "number"
                    ) ||
                    learningGR.getValue(
                        "number"
                    )
                );

            if (
                requestNumber.indexOf(
                    requestNumberFilter
                ) === -1
            ) {
                return false;
            }
        }

        if (
            courseTypeFilter &&
            String(
                learningGR.getValue(
                    "u_course_type"
                ) || ""
            ) !== courseTypeFilter
        ) {
            return false;
        }

        if (
            courseFormatFilter &&
            String(
                learningGR.getValue(
                    "u_course_format"
                ) || ""
            ) !== courseFormatFilter
        ) {
            return false;
        }

        if (
            countryFilter &&
            String(
                learningGR.getValue(
                    "u_country"
                ) || ""
            ) !== countryFilter
        ) {
            return false;
        }

        return true;
    }

    /*
     * Builds the response object consumed by the client script.
     */
    function buildApprovalRecord(
        approvalGR,
        learningGR
    ) {

        var record = {};

        record.approval_sys_id =
            approvalGR.getUniqueValue();

        record.application_sys_id =
            learningGR.getUniqueValue();

        record.number =
            getDisplayValueSafely(
                learningGR,
                "number"
            );

        record.course_title =
            getDisplayValueSafely(
                learningGR,
                "u_course_title"
            );

        record.course_type =
            getDisplayValueSafely(
                learningGR,
                "u_course_type"
            );

        record.course_type_value =
            getValueSafely(
                learningGR,
                "u_course_type"
            );

        record.course_format =
            getDisplayValueSafely(
                learningGR,
                "u_course_format"
            );

        record.course_format_value =
            getValueSafely(
                learningGR,
                "u_course_format"
            );

        record.training_country =
            getDisplayValueSafely(
                learningGR,
                "u_training_country"
            );

        record.training_provider =
            getDisplayValueSafely(
                learningGR,
                "u_training_provider_name"
            );

        record.course_start_date =
            getDisplayValueSafely(
                learningGR,
                "u_course_start_date"
            );

        record.course_end_date =
            getDisplayValueSafely(
                learningGR,
                "u_course_end_date"
            );

        record.training_hours =
            getDisplayValueSafely(
                learningGR,
                "u_total_training_hours"
            );

        record.employee_name =
            getDisplayValueSafely(
                learningGR,
                "u_employee_name"
            );

        record.employee_email =
            getDisplayValueSafely(
                learningGR,
                "u_employee_email"
            );

        record.country =
            getDisplayValueSafely(
                learningGR,
                "u_country"
            );

        record.country_value =
            getValueSafely(
                learningGR,
                "u_country"
            );

        record.manager =
            getDisplayValueSafely(
                learningGR,
                "u_direct_manager"
            );

        record.management_l2 =
            getDisplayValueSafely(
                learningGR,
                "u_management_l2"
            );

        record.l2_required =
            getDisplayValueSafely(
                learningGR,
                "u_l2_required"
            );

        record.currency =
            getDisplayValueSafely(
                learningGR,
                "u_currency"
            );

        if (!record.currency) {
            record.currency =
                getDisplayValueSafely(
                    learningGR,
                    "currency"
                );
        }

        record.course_fee =
            getDisplayValueSafely(
                learningGR,
                "u_course_fee"
            );

        record.other_expenses =
            getDisplayValueSafely(
                learningGR,
                "u_other_expenses"
            );

        record.total_cost =
            getDisplayValueSafely(
                learningGR,
                "u_total_cost"
            );

        record.ticket_status =
            getDisplayValueSafely(
                learningGR,
                STATUS_FIELD
            );

        record.ticket_status_value =
            getValueSafely(
                learningGR,
                STATUS_FIELD
            );

        record.approval_state =
            approvalGR.getDisplayValue(
                "state"
            );

        record.direct_manager_comments =
            cleanComment(
                getValueSafely(
                    learningGR,
                    MANAGER_COMMENTS_FIELD
                )
            );

        record.l2_manager_comments =
            cleanComment(
                getValueSafely(
                    learningGR,
                    L2_COMMENTS_FIELD
                )
            );

        record.hr_comments =
            cleanComment(
                getValueSafely(
                    learningGR,
                    HR_COMMENTS_FIELD
                )
            );

        record.created_on =
            approvalGR.getValue(
                "sys_created_on"
            );

        record.processing = false;
        record.actionComments = "";
        record.commentValidationError =
            false;

        return record;
    }

    /*
     * Approve or reject the selected sysapproval_approver record.
     */
    function processApprovalAction(
        targetState
    ) {

        data.successMessage = "";
        data.errorMessage = "";

        var approvalSysId =
            input &&
            input.approvalSysId
                ? String(
                    input.approvalSysId
                )
                : "";

        var comments =
            input &&
            input.comments
                ? String(input.comments).trim()
                : "";

        if (!approvalSysId) {
            data.errorMessage =
                "Approval record was not provided.";
            loadApprovalData();
            return;
        }

        if (!comments) {
            data.errorMessage =
                "Please enter the comments.";
            loadApprovalData();
            return;
        }

        var approvalGR =
            new GlideRecord(APPROVAL_TABLE);

        if (
            !approvalGR.get(
                approvalSysId
            )
        ) {
            data.errorMessage =
                "Approval record was not found.";
            loadApprovalData();
            return;
        }

        if (
            String(
                approvalGR.getValue(
                    "approver"
                )
            ) !== currentUserId
        ) {
            data.errorMessage =
                "You are not authorized to update this approval.";
            loadApprovalData();
            return;
        }

        if (
            String(
                approvalGR.getValue(
                    "state"
                )
            ) !== "requested"
        ) {
            data.errorMessage =
                "This approval is no longer pending.";
            loadApprovalData();
            return;
        }

        var learningGR =
            getLearningRecord(
                approvalGR
            );

        if (!learningGR) {
            data.errorMessage =
                "Learning application was not found.";
            loadApprovalData();
            return;
        }

        var selectedStage =
            getStageFromApplicationStatus(
                learningGR
            );

        saveStageComments(
            learningGR,
            selectedStage,
            comments
        );

        approvalGR.setValue(
            "comments",
            comments
        );

        approvalGR.setValue(
            "state",
            targetState
        );

        approvalGR.update();

        /*
         * Update the application status after approval/rejection.
         */
        if (
            targetState ===
            "approved"
        ) {

            updateApplicationAfterApproval(
                learningGR,
                selectedStage
            );

            data.successMessage =
                "The request was approved successfully.";

        } else {

            learningGR.setValue(
                STATUS_FIELD,
                "rejected"
            );

            addApplicationWorkNote(
                learningGR,
                buildWorkNoteMessage(
                    selectedStage,
                    "rejected",
                    comments
                )
            );

            learningGR.update();

            cancelOtherRequestedApprovals(
                learningGR.getUniqueValue(),
                approvalGR.getUniqueValue()
            );

            data.successMessage =
                "The request was rejected successfully.";
        }

        loadApprovalData();
    }

    /*
     * Sends the selected application back for rework.
     *
     * The approval itself remains requested so that
     * it can still be used after resubmission.
     */
    function sendBackForReview() {

        data.successMessage = "";
        data.errorMessage = "";

        var approvalSysId =
            input &&
            input.approvalSysId
                ? String(
                    input.approvalSysId
                )
                : "";

        var comments =
            input &&
            input.comments
                ? String(input.comments).trim()
                : "";

        if (!approvalSysId) {
            data.errorMessage =
                "Approval record was not provided.";
            loadApprovalData();
            return;
        }

        if (!comments) {
            data.errorMessage =
                "Please enter the comments.";
            loadApprovalData();
            return;
        }

        var approvalGR =
            new GlideRecord(APPROVAL_TABLE);

        if (
            !approvalGR.get(
                approvalSysId
            )
        ) {
            data.errorMessage =
                "Approval record was not found.";
            loadApprovalData();
            return;
        }

        if (
            String(
                approvalGR.getValue(
                    "approver"
                )
            ) !== currentUserId
        ) {
            data.errorMessage =
                "You are not authorized to update this approval.";
            loadApprovalData();
            return;
        }

        if (
            String(
                approvalGR.getValue(
                    "state"
                )
            ) !== "requested"
        ) {
            data.errorMessage =
                "This approval is no longer pending.";
            loadApprovalData();
            return;
        }

        var learningGR =
            getLearningRecord(
                approvalGR
            );

        if (!learningGR) {
            data.errorMessage =
                "Learning application was not found.";
            loadApprovalData();
            return;
        }

        var selectedStage =
            getStageFromApplicationStatus(
                learningGR
            );

        if (
            selectedStage !== "manager" &&
            selectedStage !== "l2" &&
            selectedStage !== "hr"
        ) {
            data.errorMessage =
                "The current application stage cannot be returned for review.";
            loadApprovalData();
            return;
        }

        saveStageComments(
            learningGR,
            selectedStage,
            comments
        );

        /*
         * Keep approval state as requested.
         */
        approvalGR.setValue(
            "comments",
            comments
        );

        approvalGR.update();

        if (
            selectedStage ===
            "manager"
        ) {
            learningGR.setValue(
                STATUS_FIELD,
                "return_by_manager"
            );
        }

        if (
            selectedStage ===
            "l2"
        ) {
            learningGR.setValue(
                STATUS_FIELD,
                "return_by_l2"
            );
        }

        if (
            selectedStage ===
            "hr"
        ) {
            learningGR.setValue(
                STATUS_FIELD,
                "return_by_hr"
            );
        }

        addApplicationWorkNote(
            learningGR,
            buildWorkNoteMessage(
                selectedStage,
                "sent back for review",
                comments
            )
        );

        learningGR.update();

        data.successMessage =
            "The request was sent back for review successfully.";

        loadApprovalData();
    }

    /*
     * Stores stage-specific comments on the application.
     */
    function saveStageComments(
        learningGR,
        stage,
        comments
    ) {

        if (
            stage === "manager" &&
            learningGR.isValidField(
                MANAGER_COMMENTS_FIELD
            )
        ) {
            learningGR.setValue(
                MANAGER_COMMENTS_FIELD,
                comments
            );
        }

        if (
            stage === "l2" &&
            learningGR.isValidField(
                L2_COMMENTS_FIELD
            )
        ) {
            learningGR.setValue(
                L2_COMMENTS_FIELD,
                comments
            );
        }

        if (
            stage === "hr" &&
            learningGR.isValidField(
                HR_COMMENTS_FIELD
            )
        ) {
            learningGR.setValue(
                HR_COMMENTS_FIELD,
                comments
            );
        }

        addApplicationWorkNote(
            learningGR,
            buildWorkNoteMessage(
                stage,
                "commented",
                comments
            )
        );
    }

    /*
     * Moves the application to the next stage after approval.
     */
    function updateApplicationAfterApproval(
        learningGR,
        stage
    ) {

        if (
            stage === "manager"
        ) {

            if (
                isL2ApprovalRequired(
                    learningGR
                )
            ) {
                learningGR.setValue(
                    STATUS_FIELD,
                    "pending_l2_approval"
                );
            } else {
                learningGR.setValue(
                    STATUS_FIELD,
                    "pending_hr_review"
                );
            }
        }

        if (
            stage === "l2"
        ) {
            learningGR.setValue(
                STATUS_FIELD,
                "pending_hr_review"
            );
        }

        if (
            stage === "hr"
        ) {
            learningGR.setValue(
                STATUS_FIELD,
                "approved"
            );
        }

        addApplicationWorkNote(
            learningGR,
            buildWorkNoteMessage(
                stage,
                "approved",
                input.comments
            )
        );

        learningGR.update();
    }

    /*
     * Determines whether L2 approval is required.
     */
    function isL2ApprovalRequired(
        learningGR
    ) {

        if (
            !learningGR.isValidField(
                "u_l2_required"
            )
        ) {
            return true;
        }

        var rawValue =
            String(
                learningGR.getValue(
                    "u_l2_required"
                ) || ""
            ).toLowerCase();

        return (
            rawValue === "true" ||
            rawValue === "1" ||
            rawValue === "yes"
        );
    }

    /*
     * Cancels other requested approvals for the same
     * application after rejection.
     */
    function cancelOtherRequestedApprovals(
        applicationSysId,
        currentApprovalSysId
    ) {

        var otherApprovalGR =
            new GlideRecord(APPROVAL_TABLE);

        otherApprovalGR.addQuery(
            "state",
            "requested"
        );

        otherApprovalGR.addQuery(
            "sys_id",
            "!=",
            currentApprovalSysId
        );

        otherApprovalGR.addEncodedQuery(
            "sysapproval=" +
            applicationSysId +
            "^ORdocument_id=" +
            applicationSysId
        );

        otherApprovalGR.query();

        while (otherApprovalGR.next()) {

            otherApprovalGR.setValue(
                "state",
                "not_required"
            );

            otherApprovalGR.setValue(
                "comments",
                "No longer required because another approver rejected the request."
            );

            otherApprovalGR.update();
        }
    }

    /*
     * Generates the CSV report.
     *
     * Only approvals approved by the logged-in user
     * during the last 90 days are included.
     */
    function generateApprovalReport() {

        data.downloadReady = false;
        data.fileContent = "";
        data.fileName = "";
        data.successMessage = "";
        data.errorMessage = "";

        try {

            var rows = [];
            var exportedRecordMap = {};
            var count = 0;

            var ninetyDaysAgo =
                new GlideDateTime();

            ninetyDaysAgo.addDaysUTC(
                -90
            );

            rows.push(
                createCsvRow([
                    "Request Number",
                    "Employee Name",
                    "Course Title",
                    "Ticket Status",
                    "Course Type",
                    "Course Format",
                    "Direct Manager Approver Name",
                    "Direct Manager Comments",
                    "L2 Manager Name",
                    "L2 Manager Comments",
                    "HR Approver Name",
                    "HR Approver Comments",
                    "Total Cost",
                    "Training Country",
                    "Training Provider",
                    "Total Training Hours"
                ])
            );

            var approvalGR =
                new GlideRecord(
                    APPROVAL_TABLE
                );

            approvalGR.addQuery(
                "approver",
                currentUserId
            );

            approvalGR.addQuery(
                "state",
                "approved"
            );

            approvalGR.addQuery(
                "sys_updated_on",
                ">=",
                ninetyDaysAgo
            );

            approvalGR.orderByDesc(
                "sys_updated_on"
            );

            approvalGR.query();

            while (
                approvalGR.next()
            ) {

                var learningGR =
                    getLearningRecord(
                        approvalGR
                    );

                if (!learningGR) {
                    continue;
                }

                var learningSysId =
                    learningGR.getUniqueValue();

                /*
                 * Export each application only once.
                 */
                if (
                    exportedRecordMap[
                        learningSysId
                    ]
                ) {
                    continue;
                }

                exportedRecordMap[
                    learningSysId
                ] = true;

                var approverDetails =
                    getApprovalStageDetails(
                        learningGR
                    );

                rows.push(
                    createCsvRow([
                        getDisplayValueSafely(
                            learningGR,
                            "number"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_employee_name"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_course_title"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            STATUS_FIELD
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_course_type"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_course_format"
                        ),

                        approverDetails
                            .managerName,

                        getDisplayValueSafely(
                            learningGR,
                            MANAGER_COMMENTS_FIELD
                        ),

                        approverDetails
                            .l2Name,

                        getDisplayValueSafely(
                            learningGR,
                            L2_COMMENTS_FIELD
                        ),

                        approverDetails
                            .hrName,

                        getDisplayValueSafely(
                            learningGR,
                            HR_COMMENTS_FIELD
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_total_cost"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_training_country"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_training_provider_name"
                        ),

                        getDisplayValueSafely(
                            learningGR,
                            "u_total_training_hours"
                        )
                    ])
                );

                count++;
            }

            if (
                count === 0
            ) {
                data.errorMessage =
                    "No approved records were found for you in the last 90 days.";

                return;
            }

            data.fileContent =
                rows.join("\r\n");

            var currentDate =
                new GlideDateTime()
                    .getLocalDate()
                    .toString()
                    .split("-")
                    .join("");

            data.fileName =
                "ASEAN_My_Approved_Learning_Requests_" +
                currentDate +
                ".csv";

            data.downloadReady = true;

            data.successMessage =
                count +
                " approved learning request record(s) exported.";

        } catch (error) {

            data.errorMessage =
                "Unable to generate report: " +
                error.message;

            gs.error(
                "[ASEAN Approval Report] " +
                error.message
            );
        }
    }

    /*
     * Finds Manager, L2 and HR approver names.
     */
    function getApprovalStageDetails(
        learningGR
    ) {

        var result = {
            managerName: "",
            l2Name: "",
            hrName: ""
        };

        var applicationSysId =
            learningGR.getUniqueValue();

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addEncodedQuery(
            "sysapproval=" +
            applicationSysId +
            "^ORdocument_id=" +
            applicationSysId
        );

        approvalGR.orderBy(
            "sys_created_on"
        );

        approvalGR.query();

        var stageIndex = 0;

        while (
            approvalGR.next()
        ) {

            var approverName =
                approvalGR.getDisplayValue(
                    "approver"
                );

            if (!approverName) {
                continue;
            }

            if (
                stageIndex === 0
            ) {
                result.managerName =
                    approverName;
            }

            if (
                stageIndex === 1
            ) {
                result.l2Name =
                    approverName;
            }

            if (
                stageIndex >= 2
            ) {
                result.hrName =
                    approverName;
            }

            stageIndex++;
        }

        return result;
    }

    /*
     * Creates the request-number typeahead list.
     */
    function loadRequestNumberSuggestions() {

        data.requestNumberSuggestions =
            [];

        var suggestionMap = {};

        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );

        approvalGR.addQuery(
            "state",
            "requested"
        );

        approvalGR.addQuery(
            "approver",
            currentUserId
        );

        approvalGR.orderByDesc(
            "sys_created_on"
        );

        approvalGR.setLimit(100);

        approvalGR.query();

        while (
            approvalGR.next()
        ) {

            var learningGR =
                getLearningRecord(
                    approvalGR
                );

            if (!learningGR) {
                continue;
            }

            if (
                !matchesSelectedStage(
                    learningGR,
                    approvalGR
                )
            ) {
                continue;
            }

            var requestNumber =
                getDisplayValueSafely(
                    learningGR,
                    "number"
                );

            if (
                !requestNumber ||
                suggestionMap[
                    requestNumber
                ]
            ) {
                continue;
            }

            suggestionMap[
                requestNumber
            ] = true;

            data.requestNumberSuggestions
                .push({
                    value:
                        requestNumber,

                    label:
                        requestNumber,

                    courseTitle:
                        getDisplayValueSafely(
                            learningGR,
                            "u_course_title"
                        ),

                    employeeName:
                        getDisplayValueSafely(
                            learningGR,
                            "u_employee_name"
                        )
                });
        }
    }

    /*
     * Reads choice values for filters.
     */
    function loadChoiceData() {

        data.courseTypes =
            getChoiceList(
                APPLICATION_TABLE,
                "u_course_type"
            );

        data.courseFormats =
            getChoiceList(
                APPLICATION_TABLE,
                "u_course_format"
            );

        data.countries =
            getChoiceList(
                APPLICATION_TABLE,
                "u_country"
            );
    }

    function getChoiceList(
        tableName,
        fieldName
    ) {

        var choices = [];

        var choiceGR =
            new GlideRecord(
                "sys_choice"
            );

        choiceGR.addQuery(
            "name",
            tableName
        );

        choiceGR.addQuery(
            "element",
            fieldName
        );

        choiceGR.addQuery(
            "inactive",
            false
        );

        choiceGR.addQuery(
            "language",
            gs.getSession()
                .getLanguage()
        );

        choiceGR.orderBy(
            "sequence"
        );

        choiceGR.query();

        while (
            choiceGR.next()
        ) {

            choices.push({
                value:
                    String(
                        choiceGR.getValue(
                            "value"
                        ) || ""
                    ),

                label:
                    String(
                        choiceGR.getValue(
                            "label"
                        ) || ""
                    )
            });
        }

        /*
         * Fallback to English if localized choices
         * were not found.
         */
        if (
            choices.length === 0
        ) {

            choiceGR.initialize();

            choiceGR.addQuery(
                "name",
                tableName
            );

            choiceGR.addQuery(
                "element",
                fieldName
            );

            choiceGR.addQuery(
                "inactive",
                false
            );

            choiceGR.addQuery(
                "language",
                "en"
            );

            choiceGR.orderBy(
                "sequence"
            );

            choiceGR.query();

            while (
                choiceGR.next()
            ) {

                choices.push({
                    value:
                        String(
                            choiceGR.getValue(
                                "value"
                            ) || ""
                        ),

                    label:
                        String(
                            choiceGR.getValue(
                                "label"
                            ) || ""
                        )
                });
            }
        }

        return choices;
    }

    /*
     * Returns the Learning Application referenced
     * by a sysapproval_approver record.
     */
    function getLearningRecord(
        approvalGR
    ) {

        var applicationSysId = "";

        if (
            approvalGR.isValidField(
                "sysapproval"
            ) &&
            approvalGR.getValue(
                "sysapproval"
            )
        ) {
            applicationSysId =
                String(
                    approvalGR.getValue(
                        "sysapproval"
                    )
                );
        }

        if (
            !applicationSysId &&
            approvalGR.isValidField(
                "document_id"
            ) &&
            approvalGR.getValue(
                "document_id"
            )
        ) {
            applicationSysId =
                String(
                    approvalGR.getValue(
                        "document_id"
                    )
                );
        }

        if (!applicationSysId) {
            return null;
        }

        var learningGR =
            new GlideRecord(
                APPLICATION_TABLE
            );

        if (
            !learningGR.get(
                applicationSysId
            )
        ) {
            return null;
        }

        return learningGR;
    }

    /*
     * Derives the current approval stage from the
     * Learning Application status.
     */
    function getStageFromApplicationStatus(
        learningGR
    ) {

        var applicationStatus =
            String(
                learningGR.getValue(
                    STATUS_FIELD
                ) || ""
            );

        if (
            applicationStatus ===
                "submitted" ||
            applicationStatus ===
                "pending_manager_approval"
        ) {
            return "manager";
        }

        if (
            applicationStatus ===
            "pending_l2_approval"
        ) {
            return "l2";
        }

        if (
            applicationStatus ===
            "pending_hr_review"
        ) {
            return "hr";
        }

        return "";
    }

    function addApplicationWorkNote(
        learningGR,
        message
    ) {

        if (
            !message ||
            !learningGR.isValidField(
                "work_notes"
            )
        ) {
            return;
        }

        learningGR.setValue(
            "work_notes",
            message
        );
    }

    function buildWorkNoteMessage(
        stage,
        actionText,
        comments
    ) {

        var stageLabel =
            getStageLabel(stage);

        return (
            stageLabel +
            " " +
            actionText +
            " the request.\nComments: " +
            String(comments || "")
        );
    }

    function getStageLabel(
        stage
    ) {

        if (
            stage === "manager"
        ) {
            return "Direct Manager";
        }

        if (
            stage === "l2"
        ) {
            return "L2 Manager";
        }

        if (
            stage === "hr"
        ) {
            return "HR Learning";
        }

        return "Approver";
    }

    function sortRecords() {

        data.records.sort(
            function (
                firstRecord,
                secondRecord
            ) {

                var firstValue =
                    String(
                        firstRecord.number || ""
                    );

                var secondValue =
                    String(
                        secondRecord.number || ""
                    );

                if (
                    data.sortOrder ===
                    "asc"
                ) {
                    return firstValue.localeCompare(
                        secondValue
                    );
                }

                return secondValue.localeCompare(
                    firstValue
                );
            }
        );
    }

    function getValueSafely(
        recordGR,
        fieldName
    ) {

        if (
            !recordGR ||
            !recordGR.isValidField(
                fieldName
            )
        ) {
            return "";
        }

        return String(
            recordGR.getValue(
                fieldName
            ) || ""
        );
    }

    function getDisplayValueSafely(
        recordGR,
        fieldName
    ) {

        if (
            !recordGR ||
            !recordGR.isValidField(
                fieldName
            )
        ) {
            return "";
        }

        var displayValue =
            recordGR.getDisplayValue(
                fieldName
            );

        if (
            displayValue !== null &&
            displayValue !== undefined &&
            String(displayValue) !== ""
        ) {
            return String(
                displayValue
            );
        }

        return String(
            recordGR.getValue(
                fieldName
            ) || ""
        );
    }

    function cleanComment(
        commentValue
    ) {

        var value =
            String(
                commentValue || ""
            ).trim();

        if (
            !value ||
            value === "null" ||
            value === "undefined"
        ) {
            return "";
        }

        return value;
    }

    function normalize(
        value
    ) {

        return String(
            value || ""
        )
            .toLowerCase()
            .trim();
    }

    function createCsvRow(
        values
    ) {

        var escapedValues = [];

        for (
            var index = 0;
            index < values.length;
            index++
        ) {

            escapedValues.push(
                escapeCsvValue(
                    values[index]
                )
            );
        }

        return escapedValues.join(",");
    }

    function escapeCsvValue(
        value
    ) {

        var text =
            value === null ||
            value === undefined
                ? ""
                : String(value);

        text = text.replace(
            /"/g,
            '""'
        );

        return (
            '"' +
            text +
            '"'
        );
    }

})();
